export interface Faq01Props {
  eyebrow?: string;
  title?: string;
  description?: string;
  supportTitle?: string;
  supportDescription?: string;
  supportLabel?: string;
  supportHref?: string;
  items?: { question: string; answer: string }[];
}
export const defaultItems = [
  {
    question: "Can I customise the design?",
    answer:
      "Yes. Choose a recipe, tune your tokens, and replace the content to suit your brand.",
  },
  {
    question: "Can I use my own images?",
    answer: "All media and copy are replaceable. Your assets remain yours.",
  },
  {
    question: "How do I connect my shop?",
    answer:
      "Connect your catalogue and checkout through your application. These blocks provide the interface foundations.",
  },
  {
    question: "Will it work on smaller screens?",
    answer:
      "The layout adapts from a split desktop section to a single column on smaller screens.",
  },
  {
    question: "Can I bring my own content?",
    answer:
      "Replace every question, answer and support link with the details your customers need.",
  },
];

.faq01 {
  padding: var(--website-section-padding) var(--container-padding-lg);
  background: var(--background-primary);
  color: var(--text-primary);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.faq01 *,
.faq01 *::before,
.faq01 *::after {
  box-sizing: border-box;
}
.faq01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.faq01 .faq01-layout {
  gap: var(--website-column-gap);
}
.faq01 .faq01-intro {
  flex: 0 0 32%;
  gap: var(--space-5);
  min-width: 0;
}
.faq01 :is(h2, h3, p) {
  margin: 0;
}
.faq01 .faq01-eyebrow,
.faq01 .faq01-list-heading {
  font-size: var(--typography-micro-size);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--letter-spacing-widest);
}
.faq01 .faq01-title {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  text-wrap: balance;
}
.faq01 .faq01-description {
  max-width: var(--website-copy-width);
  font-size: var(--website-copy-size);
  line-height: var(--line-height-relaxed);
}
.faq01 .faq01-support {
  width: 100%;
  margin-block-start: auto;
}
.faq01 .faq01-support h3 {
  font-size: var(--typography-caption-size);
}
.faq01 .faq01-support p {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.faq01-support-mark {
  font-size: var(--font-size-2xl);
  color: var(--brand-primary);
}
.faq01-support-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding-block-start: var(--space-4);
  border-block-start: var(--border-width-thin) solid var(--border-default);
  color: var(--text-primary);
  font-size: var(--typography-caption-size);
  text-decoration: none;
}
.faq01-support-link:hover {
  text-decoration: underline;
}
.faq01-support-link:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.faq01 .faq01-items {
  flex: 1 1 0;
  min-width: 0;
}
.faq01 .faq01-list-heading {
  gap: var(--space-4);
  padding-block-end: var(--space-5);
  color: var(--text-muted);
}
.faq01 .faq01-question {
  gap: var(--space-4);
}
.faq01-number {
  flex: 0 0 var(--space-6);
  font-family: var(--font-family-mono);
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.faq01-answer {
  padding-inline-start: calc(var(--space-6) + var(--space-4));
  max-width: var(--content-width-narrow);
}
.faq01 .faq01-answer p {
  font-size: var(--website-copy-size);
  line-height: var(--line-height-relaxed);
}
@media (max-width: 760px) {
  .faq01 {
    padding: var(--space-8) var(--container-padding);
  }
  .faq01 .faq01-layout {
    flex-direction: column;
    gap: var(--space-8);
  }
  .faq01 .faq01-intro {
    flex-basis: auto;
  }
  .faq01 .faq01-items {
    width: 100%;
  }
  .faq01 .faq01-support {
    margin-block-start: var(--space-3);
  }
}

import { useId } from "react";
import {
  Accordion,
  AccordionItem,
  Card,
  Flex,
  Heading,
  Text,
} from "@paraxe/react";
import { defaultItems, type Faq01Props } from "../shared/types";
import "../shared/style.css";
export function Faq01({
  eyebrow = "THE DETAILS / 01",
  title = "Good questions. Clear answers.",
  description = "A few things worth knowing before you make your next move.",
  supportTitle = "Still have a question?",
  supportDescription = "Our team can help with the details.",
  supportLabel = "Talk to us",
  supportHref = "/contact",
  items = defaultItems,
}: Faq01Props) {
  const headingId = useId();
  return (
    <section className="faq01" aria-labelledby={headingId}>
      <div className="faq01-inner">
        <Flex className="faq01-layout" align="stretch" fullWidth>
          <Flex className="faq01-intro" direction="column" align="start">
            <Text className="faq01-eyebrow">{eyebrow}</Text>
            <Heading id={headingId} level="h2" className="faq01-title">
              {title}
            </Heading>
            <Text className="faq01-description" tone="muted">
              {description}
            </Text>
            {supportHref && (
              <Card className="faq01-support">
                <Flex direction="column" align="start">
                  <span className="faq01-support-mark" aria-hidden="true">
                    ↗
                  </span>
                  <Heading level="h3">{supportTitle}</Heading>
                  <Text tone="muted">{supportDescription}</Text>
                  <a className="faq01-support-link" href={supportHref}>
                    {supportLabel}
                    <span aria-hidden="true">↗</span>
                  </a>
                </Flex>
              </Card>
            )}
          </Flex>
          <div className="faq01-items">
            <Flex className="faq01-list-heading" justify="between">
              <Text as="span">FREQUENTLY ASKED</Text>
              <Text as="span">
                {String(items.length).padStart(2, "0")} QUESTIONS
              </Text>
            </Flex>
            <Accordion defaultOpen={items.length ? ["question-0"] : []}>
              {items.map((item, i) => (
                <AccordionItem
                  key={i}
                  id={`question-${i}`}
                  trigger={
                    <Flex as="span" align="baseline" className="faq01-question">
                      <span className="faq01-number" aria-hidden="true">
                        {String(i + 1).padStart(2, "0")}
                      </span>
                      <span>{item.question}</span>
                    </Flex>
                  }
                >
                  <div className="faq01-answer">
                    <Text>{item.answer}</Text>
                  </div>
                </AccordionItem>
              ))}
            </Accordion>
          </div>
        </Flex>
      </div>
    </section>
  );
}
